const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const seattle = ee.Geometry.Point([-122.3321, 47.6062]).buffer(10000); // 10km buffer around Seattle
  const startDate = '2021-11-01';
  const endDate = '2021-11-30';

  // 2. Data Acquisition - GPM IMERG Daily Precipitation
  const precipCol = ee.ImageCollection('NASA/GPM_L3/IMERG_DAILY_V06')
    .filterDate(startDate, endDate)
    .filterBounds(seattle);

  const colSize = precipCol.size().getInfo();
  console.log(`November 2021 precipitation images: ${colSize}`);

  if (colSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Sum daily precipitation for the month
  const monthlyPrecip = precipCol.sum();

  // Check valid pixels
  const pixelCount = monthlyPrecip.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: seattle,
    scale: 10000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  console.log(`Valid pixels in region: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation - Get mean precipitation in mm and convert to cm
  const precipMm = monthlyPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: seattle,
    scale: 10000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  const precipCm = precipMm / 10; // Convert mm to cm

  // 5. Validation & Final Answer
  console.log(`Total November 2021 rainfall: ${precipCm.toFixed(2)} cm`);

  if (precipCm === null || precipCm === undefined || isNaN(precipCm) || precipCm < 0 || precipCm > 1000) {
    console.log("<answer>C3</answer>");
  } else if (precipCm < 20) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
